// Fallback function to get challenges for any category
export function getGameChallenges(category, gameType) {
    if (gameType === 'TRIVIA') {
        const questions = TRIVIA_DATABASE[category] || TRIVIA_DATABASE['Ramayana & Epics'];
        return { gameType: 'TRIVIA', category, questions };
    }
    else if (gameType === 'PUZZLE') {
        const puzzles = ARTIFACT_PUZZLES[category] || ARTIFACT_PUZZLES['Indus Valley Civilization'];
        return { gameType: 'PUZZLE', category, puzzles };
    }
    else {
        const words = WORD_CRYPT_DATABASE[category] || WORD_CRYPT_DATABASE['Ramayana & Epics'];
        return { gameType: 'WORD_CRYPT', category, words };
    }
}
